"""Export the trained decision tree to C++.

    python ml/export_tree.py            # ml/models/tree.joblib -> tcp/generated-tree.cc

Writes plain if/else code, so TcpLossAware needs no ML library at run time.
Rebuild ns-3 afterwards (./ns3 build).
"""
import argparse
from pathlib import Path

import joblib

from features import CONGESTION

ML_DIR = Path(__file__).resolve().parent
REPO = ML_DIR.parent

TEMPLATE = """\
// AUTO-GENERATED by ml/export_tree.py -- do not edit by hand.
// Source model: {model}
// Decision threshold on P(congestion): {threshold:.3f}
#include "loss-classifier.h"

namespace ns3
{{

bool
IsCongestionLossTree(const LossFeatures& f)
{{
{body}
}}

}} // namespace ns3
"""


def emit(tree, features, cong_col, threshold, node=0, depth=1):
    t = tree.tree_
    pad = "    " * depth
    left, right = t.children_left[node], t.children_right[node]
    if left == -1:  # leaf
        counts = t.value[node][0]
        p = counts[cong_col] / counts.sum()
        decision = "true" if p >= threshold else "false"
        return [f"{pad}return {decision}; // P(congestion)={p:.3f}, n={t.n_node_samples[node]}"]
    name = features[t.feature[node]]
    lines = [f"{pad}if (f.{name} <= {t.threshold[node]:.9g})", f"{pad}{{"]
    lines += emit(tree, features, cong_col, threshold, left, depth + 1)
    lines += [f"{pad}}}", f"{pad}else", f"{pad}{{"]
    lines += emit(tree, features, cong_col, threshold, right, depth + 1)
    lines += [f"{pad}}}"]
    return lines


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--model", type=Path, default=ML_DIR / "models" / "tree.joblib")
    ap.add_argument("--out", type=Path, default=REPO / "tcp" / "generated-tree.cc")
    args = ap.parse_args()

    saved = joblib.load(args.model)
    tree, threshold, features = saved["model"], saved["threshold"], saved["features"]
    cong_col = list(tree.classes_).index(CONGESTION)
    body = "\n".join(emit(tree, features, cong_col, threshold))
    code = TEMPLATE.format(model=args.model.name, threshold=threshold, body=body)
    args.out.write_text(code, encoding="utf-8", newline="\n")
    print(f"Wrote {args.out} (depth {tree.get_depth()}, {tree.get_n_leaves()} leaves). "
          "Rebuild ns-3 to use it.")


if __name__ == "__main__":
    main()
